import random
import numpy as np

def _blocks(P):
    P = np.array(P, dtype=float)
    ends = [i for i in range(len(P)) if P[i, i] == 1]      # absorbing, wherever they sit
    moving = [i for i in range(len(P)) if P[i, i] != 1]
    N = np.linalg.inv(np.eye(len(moving)) - P[np.ix_(moving, moving)]) if moving else None
    return P, ends, moving, N

def absorb_chances(P):
    """H[i][j]: the chance that the chain from i is absorbed at j."""
    P, ends, moving, N = _blocks(P)
    H = np.zeros(P.shape)
    for a in ends:
        H[a, a] = 1.0                                       # already absorbed
    if moving:
        B = N @ P[np.ix_(moving, ends)]                     # (I - Q)^-1 R
        H[np.ix_(moving, ends)] = B
    return H.tolist()

def steps_to_absorb(P):
    """t[i]: the expected number of steps to absorption from i."""
    P, ends, moving, N = _blocks(P)
    t = np.zeros(len(P))
    if moving:
        t[moving] = N @ np.ones(len(moving))                # (I - Q)^-1 1
    return t.tolist()

def simulate_absorb(P, start, runs, seed):
    """Share of runs from start that are absorbed at each state."""
    rng = random.Random(seed)
    n = len(P)
    counts = [0] * n
    for _ in range(runs):
        s = start
        while P[s][s] != 1:
            u, acc = rng.random(), 0.0
            for j in range(n):
                acc += P[s][j]
                if u < acc:
                    break
            s = j
        counts[s] += 1
    return [c / runs for c in counts]
